package com.sonledev.enterprise.part1;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
@Slf4j
@Service
@RequiredArgsConstructor
public class EnterprisePart1Service {
private final ExternalApiClient apiClient;
private final EnterpriseRepository repository;
@Transactional(rollbackFor = Exception.class)
public BusinessResponse executeEnterpriseProcess(BusinessRequest request) {
log.info("Starting enterprise execution for process part 1 with ID: {}", request.getI
d());
// Validate domain invariants
validateRequest(request);
// Execute core business logic
var entity = repository.findById(request.getId())
.orElseThrow(() -> new ResourceNotFoundException("Entity not found: " + request.g
etId()));
entity.updateStatus(BusinessStatus.PROCESSING);
repository.save(entity);
log.info("Successfully completed process part 1");
return new BusinessResponse(entity.getId(), "SUCCESS", System.currentTimeMillis());
}
private void validateRequest(BusinessRequest request) {
if (request == null || request.getId() == null) {
throw new IllegalArgumentException("Invalid request payload for part 1");
}
}
}
